// PANTALLA: Home publica
// ══════════════════════════════════════════════════════════════════════════════
function HomePublica({ onAcceder, club, onVolver, currentUser, onEntrarDirecto }) {
  const c = club || CLUBS[0];
  if (!c) return null;
  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">
      <div className="bg-black border-b border-zinc-800 flex items-center justify-between px-5 py-3">
        <div className="flex flex-col leading-none">
          <span className="text-zinc-500 text-xs uppercase tracking-widest">{c.deporte}</span>
          <span className="text-white text-lg font-black uppercase tracking-wide">{c.nombreCorto}</span>
        </div>
        <div className="flex items-center gap-3">
          {onVolver && <button onClick={onVolver} className="text-zinc-500 text-xs hover:text-white transition-all">← Clubes</button>}
          {currentUser ? (
          <div className="flex items-center gap-2">
            <div className="text-right">
              <div className="text-xs text-white font-semibold">{currentUser.nombre}</div>
              <div className="text-xs capitalize" style={{color: c.colorAccent}}>{currentUser.rol}</div>
            </div>
            <button onClick={onEntrarDirecto} className="text-xs text-white border px-4 py-2 rounded-lg hover:bg-zinc-800 transition-all" style={{borderColor: c.colorAccent}}>Entrar</button>
          </div>
        ) : (
          <button onClick={onAcceder} className="text-xs text-white border border-zinc-600 px-4 py-2 rounded-lg hover:bg-zinc-800 transition-all">Acceder</button>
        )}
        </div>
      </div>
      <div className="bg-black border-b border-zinc-800 py-10 text-center">
        <div className="flex flex-col items-center mb-4">
          <span className="text-zinc-500 text-xs uppercase tracking-widest mb-1">{c.deporte}</span>
          <span className="text-white text-4xl font-black uppercase">{c.nombreCorto}</span>
        </div>
        <p className="text-zinc-500 text-sm mb-4">{c.ciudad}</p>
        <div className="flex gap-2 justify-center flex-wrap">
          <span className="text-xs px-3 py-1 rounded-full bg-zinc-800 text-zinc-300 border border-zinc-700">{c.emoji} {c.deporte}</span>
          <span className="text-xs px-3 py-1 rounded-full bg-zinc-800 text-zinc-300 border border-zinc-700">{c.equipos.length} equipos</span>
          <span className="text-xs px-3 py-1 rounded-full bg-zinc-800 text-zinc-300 border border-zinc-700">Temporada 2025-26</span>
        </div>
      </div>
      <div className="p-5 border-b border-zinc-800">
        <h2 className="text-sm font-bold text-white mb-3">Resultados recientes</h2>
        <Card>
          {c.deporte === "Baloncesto" ? (
            [["Infantil A","72-68","V"],["Cadete A","58-61","D"],["Junior A","81-75","V"]].map(([eq,res,r]) => (
              <div key={eq} className="flex items-center gap-3 py-2 border-b border-zinc-800 last:border-0">
                <span className="text-zinc-400 text-sm flex-1">{eq}</span>
                <span className="text-white font-bold text-sm">{res}</span>
                <Badge color={r==="V"?"green":"red"}>{r==="V"?"Victoria":"Derrota"}</Badge>
              </div>
            ))
          ) : (
            [["Infantil","2-1","V"],["Juvenil B","1-1","E"],["Amateur","0-2","D"]].map(([eq,res,r]) => (
              <div key={eq} className="flex items-center gap-3 py-2 border-b border-zinc-800 last:border-0">
                <span className="text-zinc-400 text-sm flex-1">{eq}</span>
                <span className="text-white font-bold text-sm">{res}</span>
                <Badge color={r==="V"?"green":r==="D"?"red":"yellow"}>{r==="V"?"Victoria":r==="D"?"Derrota":"Empate"}</Badge>
              </div>
            ))
          )}
        </Card>
      </div>
      <div className="p-5 border-b border-zinc-800">
        <h2 className="text-sm font-bold text-white mb-3">Ultimas noticias</h2>
        <Card>
          {c.deporte === "Baloncesto" ? (
            [["Captacion","Inscripcion abierta para la temporada 2026-27","Hace 2h"],["Resultados","El Junior A gana 81-75 en el primer amistoso","Ayer"],["Club","Presentacion del cuerpo tecnico de baloncesto 2026-27","Hace 3 dias"]].map(([tag,title,meta]) => (
              <div key={title} className="py-2 border-b border-zinc-800 last:border-0">
                <div className="text-xs font-semibold mb-0.5" style={{color: c.colorAccent}}>{tag}</div>
                <div className="text-sm font-semibold text-white">{title}</div>
                <div className="text-xs text-zinc-500">{meta}</div>
              </div>
            ))
          ) : (
            [["Captacion","Inscripcion abierta para la temporada 2026-27","Hace 2h"],["Resultados","El Infantil gana 2-1 en el primer amistoso","Ayer"],["Club","Presentacion del cuerpo tecnico 2026-27","Hace 3 dias"]].map(([tag,title,meta]) => (
              <div key={title} className="py-2 border-b border-zinc-800 last:border-0">
                <div className="text-xs font-semibold mb-0.5" style={{color: c.colorAccent}}>{tag}</div>
                <div className="text-sm font-semibold text-white">{title}</div>
                <div className="text-xs text-zinc-500">{meta}</div>
              </div>
            ))
          )}
        </Card>
      </div>
      <div className="p-5 border-b border-zinc-800">
        <h2 className="text-sm font-bold text-white mb-3">Nuestros equipos</h2>
        <div className="grid grid-cols-3 gap-2">
          {[["Infantil","Sub-12"],["Cadete","Sub-14"],["Juvenil A","Sub-18"],["Juvenil B","Sub-18"],["Amateur","Senior"]].map(([name,cat]) => (
            <Card key={name} className="text-center">
              <div className="text-white text-sm font-bold">{name}</div>
              <div className="text-zinc-500 text-xs">{cat}</div>
            </Card>
          ))}
        </div>
      </div>
      <div className="p-5">
        <h2 className="text-sm font-bold text-white mb-3">Inscripcion</h2>
        <Card className="flex items-center justify-between gap-4">
          <div>
            <div className="text-white font-semibold text-sm">Inscripcion abierta 2026-27</div>
            <div className="text-zinc-500 text-xs">Plazas limitadas en todas las categorias</div>
          </div>
          <Btn onClick={onAcceder}>Apuntarse</Btn>
        </Card>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// PANTALLA: Login con email
// ══════════════════════════════════════════════════════════════════════════════
function LoginScreen({ onVolver, onLoginOk, onIrRegistro, onLoginLegacy, club }) {
  const c = club || CLUBS[0];
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [recordar, setRecordar] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("mgd_remember");
      if (saved) {
        const d = JSON.parse(saved);
        if (d.email) setEmail(d.email);
        if (d.password) setPass(d.password);
        setRecordar(true);
      }
    } catch(e) {}
  }, []);

  const handleLogin = async () => {
    if (!email || !pass) { setError("Introduce tu email y contrasena."); return; }
    setLoading(true); setError("");
    const res = club?.id === "internacional" ? await loginInternacional({ email, password: pass }) : await loginUsuario({ email, password: pass, clubId: club?.id || "magdalena" });
    setLoading(false);
    if (!res.ok) { setError(res.error); return; }
    if (recordar) {
      try { localStorage.setItem("mgd_remember", JSON.stringify({ email, password: pass })); } catch(e) {}
    } else {
      try { localStorage.removeItem("mgd_remember"); } catch(e) {}
    }
    try { localStorage.setItem("mgd_session", JSON.stringify({ user: res.user, clubId: club?.id || clubActual?.id || "magdalena" })); } catch(e) {}
    onLoginOk(res.user);
  };

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">
      <div className="bg-black border-b border-zinc-800 flex items-center justify-between px-5 py-3">
        <div className="flex flex-col leading-none">
          <span className="text-zinc-500 text-xs uppercase tracking-widest">{c.deporte}</span>
          <span className="text-white text-lg font-black uppercase tracking-wide">{c.nombreCorto}</span>
        </div>
        <button onClick={onVolver} className="text-zinc-400 text-xs hover:text-white">Volver</button>
      </div>
      <div className="flex-1 flex items-center justify-center p-6">
        <div className="w-full max-w-sm">
          <div className="text-center mb-6">
            <h1 className="text-white text-xl font-bold mb-1">Accede a tu cuenta</h1>
            <p className="text-zinc-500 text-sm">Introduce tus credenciales</p>
          </div>
          {error && <div className="bg-red-900/40 border border-red-800 text-red-300 text-xs p-3 rounded-lg mb-4">{error}</div>}
          <div className="space-y-3">
            <Input label="Email" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@email.com" />
            <Input label="Contrasena" type="password" value={pass} onChange={e => setPass(e.target.value)} placeholder="••••••••" onKeyDown={e => e.key === "Enter" && handleLogin()} />
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={recordar} onChange={e => setRecordar(e.target.checked)} className="w-4 h-4" />
              <span className="text-zinc-400 text-xs">Recordar email y contrasena</span>
            </label>
            <Btn onClick={handleLogin} disabled={loading} className="w-full justify-center">
              {loading ? "Entrando..." : "Entrar"}
            </Btn>
          </div>
          <div className="text-center mt-4">
            <span className="text-zinc-500 text-xs">No tienes cuenta? </span>
            <button onClick={onIrRegistro} className="text-red-400 text-xs hover:text-red-300">Registrate</button>
          </div>
          <div className="text-center mt-2">
            <button onClick={onLoginLegacy} className="text-zinc-600 text-xs hover:text-zinc-400">Acceso con clave de equipo</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// PANTALLA: Registro en 2 pasos
// ══════════════════════════════════════════════════════════════════════════════
function RegistroScreen({ onVolver, onRegistroOk, club }) {
  const c = club || CLUBS[0];
  const [paso, setPaso] = useState(1);
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [pass1, setPass1] = useState("");
  const [pass2, setPass2] = useState("");
  const [rol, setRol] = useState("familiar");
  const [codigo, setCodigo] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [rolFinal, setRolFinal] = useState(null);
  const [equipoSel, setEquipoSel] = useState(TEAMS[0]);

  const irPaso2 = () => {
    if (!nombre.trim() || !email.trim()) { setError("Rellena nombre y email."); return; }
    if (pass1.length < 6) { setError("La contrasena debe tener al menos 6 caracteres."); return; }
    if (pass1 !== pass2) { setError("Las contrasenas no coinciden."); return; }
    setError(""); setPaso(2);
  };

  const handleRegistro = async () => {
    setLoading(true); setError("");
    try {
      if (rol !== "familiar") {
        const codigosEquipo = c.passwords?.equipos || {};
        const coordPwd = c.passwords?.coordinador || "";
        const codigoOk = rol === "coordinador"
          ? codigo.trim().toUpperCase() === coordPwd
          : codigo.trim().toUpperCase() === (codigosEquipo[equipoSel] || "");
        if (!codigoOk) { setError("Codigo incorrecto para " + (rol === "coordinador" ? "coordinador" : equipoSel) + "."); setLoading(false); return; }
      }
      const res = await registrarUsuario({ nombre, email, password: pass1, rol, equipo: rol === "entrenador" ? equipoSel : null, club: c?.id || "magdalena" });
      if (!res.ok) { setError(res.error); setLoading(false); return; }
      setRolFinal(rol); setPaso(3);
      setTimeout(() => onRegistroOk(res.user), 1500);
    } catch(e) {
      setError("Error al crear la cuenta: " + e.message);
    }
    setLoading(false);
  };

  const ROLES = [
    { val: "familiar", label: "Jugador / familia", desc: "Sin codigo - acceso libre" },
    { val: "entrenador", label: "Entrenador", desc: "Requiere codigo de entrenador" },
    { val: "coordinador", label: "Coordinador", desc: "Requiere codigo de coordinador" },
  ];

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">
      <div className="bg-black border-b border-zinc-800 flex items-center justify-between px-5 py-3">
        <div className="flex flex-col leading-none">
          <span className="text-zinc-500 text-xs uppercase tracking-widest">{c.deporte}</span>
          <span className="text-white text-lg font-black uppercase tracking-wide">{c.nombreCorto}</span>
        </div>
        <button onClick={onVolver} className="text-zinc-400 text-xs hover:text-white">Volver</button>
      </div>
      <div className="flex-1 flex items-center justify-center p-6">
        <div className="w-full max-w-sm">
          <div className="flex items-center gap-2 mb-6">
            {[1,2,3].map((n,i) => (
              <React.Fragment key={n}>
                <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold ${paso > n ? "bg-red-600 text-white" : paso === n ? "bg-red-700 text-white" : "bg-zinc-800 text-zinc-500"}`}>
                  {paso > n ? "✓" : n}
                </div>
                {i < 2 && <div className={`flex-1 h-0.5 ${paso > n ? "bg-red-600" : "bg-zinc-800"}`} />}
              </React.Fragment>
            ))}
          </div>
          {error && <div className="bg-red-900/40 border border-red-800 text-red-300 text-xs p-3 rounded-lg mb-4">{error}</div>}
          {paso === 1 && (
            <div className="space-y-3">
              <h1 className="text-white text-lg font-bold mb-1">Crea tu cuenta</h1>
              <Input label="Nombre completo" value={nombre} onChange={e => setNombre(e.target.value)} placeholder="Juan Garcia" />
              <Input label="Email" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@email.com" />
              <Input label="Contrasena" type="password" value={pass1} onChange={e => setPass1(e.target.value)} placeholder="Minimo 6 caracteres" />
              <Input label="Repite la contrasena" type="password" value={pass2} onChange={e => setPass2(e.target.value)} placeholder="••••••••" onKeyDown={e => e.key === "Enter" && irPaso2()} />
              <Btn onClick={irPaso2} className="w-full justify-center">Siguiente</Btn>
            </div>
          )}
          {paso === 2 && (
            <div className="space-y-3">
              <h1 className="text-white text-lg font-bold mb-1">Cual es tu rol?</h1>
              <div className="space-y-2">
                {ROLES.map(r => (
                  <div key={r.val} onClick={() => { setRol(r.val); setCodigo(""); }}
                    className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${rol === r.val ? "border-red-600 bg-red-900/20" : "border-zinc-800 bg-zinc-900 hover:border-zinc-600"}`}>
                    <div className="flex-1">
                      <div className="text-white text-sm font-semibold">{r.label}</div>
                      <div className="text-zinc-500 text-xs">{r.desc}</div>
                    </div>
                    {rol === r.val && <span className="text-red-400 text-sm">✓</span>}
                  </div>
                ))}
              </div>
              {rol !== "familiar" && (
                <div className="space-y-2">
                  <Input label="Codigo de acceso" value={codigo} onChange={e => setCodigo(e.target.value.toUpperCase())} placeholder="Pidelo a tu coordinador" />
                  {rol === "entrenador" && (
                    <div className="flex flex-col gap-1">
                      <label className="text-xs text-zinc-400 uppercase tracking-wider">Tu equipo</label>
                      <select value={equipoSel} onChange={e => setEquipoSel(e.target.value)} className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm focus:outline-none focus:border-red-600 w-full">{TEAMS.map(t => <option key={t}>{t}</option>)}</select>
                    </div>
                  )}
                </div>
              )}
              <Btn onClick={handleRegistro} disabled={loading} className="w-full justify-center">
                {loading ? "Creando cuenta..." : "Crear cuenta"}
              </Btn>
              <Btn variant="secondary" onClick={() => { setPaso(1); setError(""); }} className="w-full justify-center">Atras</Btn>
            </div>
          )}
          {paso === 3 && (
            <div className="text-center py-4">
              <div className="w-14 h-14 bg-red-700 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4">✓</div>
              <h1 className="text-white text-xl font-bold mb-2">Cuenta creada!</h1>
              <p className="text-zinc-500 text-sm">Entrando al club...</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}



// ══════════════════════════════════════════════════════════════════════════════
// SECCION: Banco de jugadores del club
// ══════════════════════════════════════════════════════════════════════════════
function BancoJugadoresSection({ clubActual, onAddToEquipo }) {
  const clubInfo = CLUBS.find(c => c.id === clubActual?.id) || CLUBS[0];
  const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
  const [jugadores, setJugadores] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [search, setSearch] = React.useState("");
  const [showForm, setShowForm] = React.useState(false);
  const [editJ, setEditJ] = React.useState(null);
  const [form, setForm] = React.useState({ nombre:"", fechaNac:"", dni:"", telefono:"", posicion:"", estado:"disponible", notas:"" });
  const [tab, setTab] = React.useState("todos");
  const [menuBanco, setMenuBanco] = React.useState(null);
  const [seleccion, setSeleccion] = React.useState([]);
  const [equiposFiltro, setEquiposFiltro] = React.useState([]);
  const toggleEquipoFiltro = (eq) => setEquiposFiltro(s => s.includes(eq) ? s.filter(x => x !== eq) : [...s, eq]);
  const toggleSel = (id) => setSeleccion(s => s.includes(id) ? s.filter(x => x !== id) : [...s, id]);
  const [filtroPosicion, setFiltroPosicion] = React.useState("");
  const [filtroAnioMin, setFiltroAnioMin] = React.useState("");
  const [filtroAnioMax, setFiltroAnioMax] = React.useState("");

  React.useEffect(() => {
    loadBancoJugadores(prefix).then(js => { setJugadores(js); setLoading(false); }).catch(() => setLoading(false));
  }, [prefix]);

  const POSICIONES = ["Portero","Defensa Central","Lateral Derecho","Lateral Izquierdo","Mediocentro","Mediapunta","Extremo Derecho","Extremo Izquierdo","Delantero"];
  const ESTADOS = ["disponible","probando","lesionado","inactivo"];
  const ESTADO_COLOR = { disponible:"green", probando:"yellow", lesionado:"red", inactivo:"zinc" };

  const save = async (nuevos) => {
    await saveBancoJugadores(prefix, nuevos);
    setJugadores(nuevos);
  };

  const openForm = (j = null) => {
    setEditJ(j?.id || null);
    setForm(j ? { nombre:j.nombre||"", fechaNac:j.fechaNac||"", dni:j.dni||"", telefono:j.telefono||"", posicion:j.posicion||"", estado:j.estado||"disponible", notas:j.notas||"" } : { nombre:"", fechaNac:"", dni:"", telefono:"", posicion:"", estado:"disponible", notas:"" });
    setShowForm(true);
  };

  const guardarJugador = async () => {
    if (!form.nombre.trim()) return;
    let nuevos;
    if (editJ) {
      nuevos = jugadores.map(j => j.id === editJ ? { ...j, ...form } : j);
    } else {
      const nuevo = { ...form, id: Date.now().toString(), creadoEn: new Date().toISOString() };
      nuevos = [...jugadores, nuevo];
    }
    await save(nuevos);
    setShowForm(false);
    setEditJ(null);
  };

  const eliminarJugador = async (id) => {
    if (!window.confirm("Eliminar jugador?")) return;
    await save(jugadores.filter(j => j.id !== id));
  };

  const calcEdad = (fechaNac) => {
    if (!fechaNac) return "-";
    const hoy = new Date();
    const nac = new Date(fechaNac);
    return hoy.getFullYear() - nac.getFullYear() - (hoy < new Date(hoy.getFullYear(), nac.getMonth(), nac.getDate()) ? 1 : 0);
  };

  const aniosDisponibles = [...new Set(jugadores.map(j => j.fechaNac ? new Date(j.fechaNac).getFullYear().toString() : null).filter(Boolean))].sort();

  const jugadoresFiltrados = jugadores
    .filter(j => tab === "todos" ? true : j.estado === tab)
    .filter(j => !search || j.nombre.toLowerCase().includes(search.toLowerCase()))
    .filter(j => !filtroPosicion || j.posicion === filtroPosicion || (j.posicionesSecundarias && j.posicionesSecundarias.includes(filtroPosicion)))
    .filter(j => { if (!filtroAnioMin && !filtroAnioMax) return true; const anio = j.fechaNac ? new Date(j.fechaNac).getFullYear() : null; if (!anio) return false; if (filtroAnioMin && anio < parseInt(filtroAnioMin)) return false; if (filtroAnioMax && anio > parseInt(filtroAnioMax)) return false; return true; })
    .sort((a, b) => (a.fechaNac || "").localeCompare(b.fechaNac || ""));

  const [importing, setImporting] = React.useState(false);

  const actualizarFechas = async () => {
    setImporting(true);
    try {
      const dbSnap = await loadData();
      if (!dbSnap) { setImporting(false); return; }
      const todosJugadores = [];
      Object.entries(dbSnap).forEach(([equipo, datos]) => {
        if (!datos || typeof datos !== "object") return;
        [...(datos.players || []), ...(datos.probando || [])].forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (nombre) todosJugadores.push({ nombre, fechaNacimiento: p.fechaNacimiento || "", posicion: p.posicionPrincipal || p.posicion || "", posicionesSecundarias: p.positions || [], telefono: p.phone || p.telefono || p.phone2 || "", dni: p.dni || "" });
        });
      });
      let actualizados = 0;
      const nuevoBanco = jugadores.map(j => {
        const match = todosJugadores.find(p => p.nombre.toLowerCase().trim() === j.nombre.toLowerCase().trim());
        if (match && (!j.fechaNac || j.fechaNac === "") && match.fechaNacimiento) {
          actualizados++;
          return { ...j, fechaNac: match.fechaNacimiento, posicion: j.posicion || match.posicion, posicionesSecundarias: j.posicionesSecundarias?.length ? j.posicionesSecundarias : match.posicionesSecundarias, telefono: j.telefono || match.telefono, dni: j.dni || match.dni };
        }
        return j;
      });
      await saveBancoJugadores(prefix, nuevoBanco);
      setJugadores(nuevoBanco);
      alert(actualizados + " jugadores actualizados con fecha de nacimiento.");
    } catch(e) { alert("Error: " + e.message); }
    setImporting(false);
  };

  const importarDeEquipos = async () => {
    setImporting(true);
    try {
      const dbSnap = await loadData();
      if (!dbSnap) { setImporting(false); return; }
      const bancoActual = [...jugadores];
      const idsExistentes = new Set(bancoActual.map(j => j.nombre?.toLowerCase()?.trim()));
      let nuevos = 0;
      Object.entries(dbSnap).forEach(([equipo, datos]) => {
        if (!datos || typeof datos !== "object") return;
        const players = datos.players || [];
        players.forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (!nombre) return;
          if (!idsExistentes.has(nombre.toLowerCase())) {
            bancoActual.push({
              id: Date.now().toString() + Math.random().toString(36).slice(2),
              nombre,
              fechaNac: p.fechaNacimiento || p.fechaNac || p.dob || "",
              dni: p.dni || "",
              telefono: p.phone || p.telefono || p.phone2 || "",
              posicion: p.posicionPrincipal || p.posicion || "",
              posicionesSecundarias: p.positions || p.posicionesSecundarias || [],
              estado: "disponible",
              equipoOrigen: equipo,
              notas: "",
              creadoEn: new Date().toISOString()
            });
            idsExistentes.add(nombre.toLowerCase());
            nuevos++;
          }
        });
        const probando = datos.probando || [];
        probando.forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (!nombre) return;
          if (!idsExistentes.has(nombre.toLowerCase())) {
            bancoActual.push({
              id: Date.now().toString() + Math.random().toString(36).slice(2),
              nombre,
              fechaNac: p.fechaNacimiento || p.fechaNac || p.dob || "",
              dni: p.dni || "",
              telefono: p.phone || p.telefono || "",
              posicion: p.posicionPrincipal || p.posicion || "",
              posicionesSecundarias: p.positions || p.posicionesSecundarias || [],
              estado: "probando",
              equipoOrigen: equipo,
              notas: "",
              creadoEn: new Date().toISOString()
            });
            idsExistentes.add(nombre.toLowerCase());
            nuevos++;
          }
        });
      });
      await saveBancoJugadores(prefix, bancoActual);
      setJugadores(bancoActual);
      alert(nuevos + " jugadores importados al banco.");
    } catch(e) {
      alert("Error al importar: " + e.message);
    }
    setImporting(false);
  };

  if (loading) return <div className="p-6 text-zinc-500 text-sm">Cargando...</div>;

  return (
    <div className="p-6 max-w-4xl">
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between mb-6">
        <h2 className="text-xl font-bold text-white">Banco de Jugadores</h2>
        <div className="flex gap-2 flex-wrap">
          <Btn small variant="secondary" onClick={actualizarFechas} disabled={importing}>🔄 Fechas</Btn>
          <Btn small variant="secondary" onClick={importarDeEquipos} disabled={importing}>{importing ? "Importando..." : "📥 Importar"}</Btn>
          <Btn small onClick={() => openForm()}>+ Añadir</Btn>
        </div>
      </div>

      {showForm && (
        <Card className="mb-6">
          <h3 className="text-sm font-semibold text-white mb-4">{editJ ? "Editar jugador" : "Nuevo jugador"}</h3>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <Input label="Nombre completo" value={form.nombre} onChange={e => setForm({...form, nombre:e.target.value})} placeholder="Nombre y apellidos" />
            <Input label="Fecha de nacimiento" type="date" value={form.fechaNac} onChange={e => setForm({...form, fechaNac:e.target.value})} />
            <Input label="DNI / NIE" value={form.dni} onChange={e => setForm({...form, dni:e.target.value})} placeholder="12345678A" />
            <Input label="Teléfono" value={form.telefono} onChange={e => setForm({...form, telefono:e.target.value})} placeholder="+34 600 000 000" />
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Posición</label>
              <select value={form.posicion} onChange={e => setForm({...form, posicion:e.target.value})}
                className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm w-full">
                <option value="">Sin posición</option>
                {POSICIONES.map(p => <option key={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Estado</label>
              <select value={form.estado} onChange={e => setForm({...form, estado:e.target.value})}
                className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm w-full">
                {ESTADOS.map(e => <option key={e}>{e}</option>)}
              </select>
            </div>
          </div>
          <Input label="Notas" value={form.notas} onChange={e => setForm({...form, notas:e.target.value})} placeholder="Observaciones..." />
          <div className="flex gap-2 mt-3">
            <Btn onClick={guardarJugador}>Guardar</Btn>
            <Btn variant="secondary" onClick={() => { setShowForm(false); setEditJ(null); }}>Cancelar</Btn>
          </div>
        </Card>
      )}

      <div className="flex gap-2 mb-4 flex-wrap">
        {["todos","disponible","probando","lesionado","inactivo"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-all ${tab===t?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>
            {t === "todos" ? `Todos (${jugadores.length})` : `${t} (${jugadores.filter(j=>j.estado===t).length})`}
          </button>
        ))}
        <div className="w-full md:w-auto md:ml-auto flex gap-2 flex-wrap">
          <select value={filtroAnioMin} onChange={e => setFiltroAnioMin(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Desde</option>
            {aniosDisponibles.map(a => <option key={a}>{a}</option>)}
          </select>
          <select value={filtroAnioMax} onChange={e => setFiltroAnioMax(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Hasta</option>
            {aniosDisponibles.map(a => <option key={a}>{a}</option>)}
          </select>
          <select value={filtroPosicion} onChange={e => setFiltroPosicion(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Todas las posiciones</option>
            {POSICIONES.map(p => <option key={p}>{p}</option>)}
          </select>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar jugador..."
            className="bg-zinc-900 border border-zinc-700 rounded px-3 py-1.5 text-zinc-100 text-xs w-40 focus:outline-none" />
        </div>
      </div>

      <Card>
        {jugadoresFiltrados.length === 0 && <p className="text-zinc-500 text-sm py-2">No hay jugadores.</p>}
                {(() => {
          const equiposDisponibles = [...new Set(jugadores.map(j => j.equipoOrigen || "Sin equipo"))].sort();
          if (equiposDisponibles.length <= 1) return null;
          return (
            <div className="mb-3">
              <p className="text-xs text-zinc-500 uppercase tracking-wider mb-1.5">Filtrar por equipo{equiposFiltro.length > 0 ? ` (${equiposFiltro.length})` : ""}</p>
              <div className="flex flex-wrap gap-1.5">
                {equiposDisponibles.map(eq => (
                  <button key={eq} onClick={() => toggleEquipoFiltro(eq)}
                    className={`text-xs px-3 py-1.5 rounded-full border transition-all ${equiposFiltro.includes(eq) ? "bg-red-700 border-red-500 text-white font-semibold" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                    {eq}
                  </button>
                ))}
                {equiposFiltro.length > 0 && (
                  <button onClick={() => setEquiposFiltro([])}
                    className="text-xs px-3 py-1.5 rounded-full border border-zinc-600 text-zinc-300 hover:text-white transition-all">
                    ✕ Quitar filtro
                  </button>
                )}
              </div>
            </div>
          );
        })()}
        {jugadoresFiltrados.filter(j => equiposFiltro.length === 0 || equiposFiltro.includes(j.equipoOrigen || "Sin equipo")).map(j => (
          <div key={j.id} onClick={() => setMenuBanco(j)}
            className="flex items-center gap-3 py-3 border-b border-zinc-800 last:border-0 cursor-pointer active:bg-zinc-800/50 transition-colors">
            <input type="checkbox" checked={seleccion.includes(j.id)}
              onClick={e => e.stopPropagation()}
              onChange={() => toggleSel(j.id)}
              className="w-5 h-5 accent-red-600 shrink-0 cursor-pointer" />
            <div className="w-9 h-9 rounded-full bg-zinc-700 flex items-center justify-center text-white text-sm font-bold flex-shrink-0">
              {j.nombre[0]?.toUpperCase()}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-white text-sm font-semibold truncate">{j.nombre}</div>
              <div className="text-zinc-500 text-xs truncate">
                {[j.fechaNac ? new Date(j.fechaNac).getFullYear() : null, j.posicion, j.equipoOrigen].filter(Boolean).join(" · ") || "Sin datos"}
              </div>
            </div>
            <Badge color={ESTADO_COLOR[j.estado] || "zinc"}>{j.estado}</Badge>
            <span className="text-zinc-500 text-lg shrink-0">›</span>
          </div>
        ))}
      </Card>

      {/* Barra de acciones de seleccion multiple */}
      {seleccion.length > 0 && (
        <div className="fixed bottom-20 md:bottom-6 inset-x-3 md:inset-x-auto md:right-6 z-50 bg-zinc-800 border border-zinc-600 rounded-2xl shadow-2xl p-3 flex items-center gap-2 flex-wrap md:max-w-md">
          <span className="text-white text-sm font-semibold px-1">{seleccion.length} seleccionado{seleccion.length > 1 ? "s" : ""}</span>
          <div className="flex gap-2 ml-auto">
            {onAddToEquipo && <Btn small onClick={() => {
              const elegidos = jugadores.filter(j => seleccion.includes(j.id));
              onAddToEquipo(elegidos);
              setSeleccion([]);
            }}>➕ Al equipo</Btn>}
            <Btn small variant="danger" onClick={() => {
              if (!window.confirm("¿Eliminar " + seleccion.length + " jugador(es) del banco?")) return;
              const restantes = jugadores.filter(j => !seleccion.includes(j.id));
              save(restantes);
              setSeleccion([]);
            }}>🗑️</Btn>
            <Btn small variant="ghost" onClick={() => setSeleccion([])}>✕</Btn>
          </div>
        </div>
      )}

      {/* Ficha del jugador del banco */}
      {menuBanco && (() => {
        const j = jugadores.find(x => x.id === menuBanco.id) || menuBanco;
        return (
          <div className="fixed inset-0 bg-black/70 z-[60] flex items-end md:items-center md:justify-center" onClick={() => setMenuBanco(null)}>
            <div className="bg-zinc-900 border-t border-zinc-700 md:border md:rounded-xl rounded-t-2xl w-full md:max-w-md p-5 pb-8 space-y-4 max-h-[85vh] overflow-auto" onClick={e => e.stopPropagation()}>
              <div className="w-10 h-1 bg-zinc-700 rounded-full mx-auto md:hidden" />
              <div className="text-center">
                <div className="w-14 h-14 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xl font-bold mx-auto mb-2">
                  {j.nombre[0]?.toUpperCase()}
                </div>
                <p className="text-white font-bold text-lg">{j.nombre}</p>
                <div className="mt-1"><Badge color={ESTADO_COLOR[j.estado] || "zinc"}>{j.estado}</Badge></div>
              </div>
              <div className="bg-zinc-800/60 rounded-xl p-4 space-y-1.5 text-sm">
                {j.fechaNac && <p className="text-zinc-300">🎂 {calcEdad(j.fechaNac)} años ({new Date(j.fechaNac).toLocaleDateString("es-ES")})</p>}
                {j.posicion && <p className="text-zinc-300">⚽ {j.posicion}{(j.posicionesSecundarias||[]).length > 0 ? " · " + j.posicionesSecundarias.join(", ") : ""}</p>}
                {j.telefono && <p className="text-zinc-300">📞 {j.telefono}</p>}
                {j.dni && <p className="text-zinc-300 font-mono">🪪 {j.dni}</p>}
                {j.equipoOrigen && <p className="text-zinc-400">📍 {j.equipoOrigen}</p>}
                {j.notas && <p className="text-zinc-400 italic pt-1 border-t border-zinc-700">{j.notas}</p>}
                {!j.fechaNac && !j.posicion && !j.telefono && !j.dni && <p className="text-zinc-600">Sin más datos.</p>}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {onAddToEquipo && <Btn variant="secondary" onClick={() => { setMenuBanco(null); onAddToEquipo(j); }}>➕ A equipo</Btn>}
                <Btn variant="secondary" onClick={() => { setMenuBanco(null); openForm(j); }}>✏️ Editar</Btn>
                <Btn variant="danger" onClick={() => { setMenuBanco(null); eliminarJugador(j.id); }}>🗑️ Eliminar</Btn>
              </div>
              <Btn variant="ghost" className="w-full justify-center" onClick={() => setMenuBanco(null)}>Cerrar</Btn>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// SECCION: Gestión de equipos y usuarios del club
// ══════════════════════════════════════════════════════════════════════════════
function GestionClubSection({ clubActual, onEquiposChange }) {
  const clubInfo = CLUBS.find(c => c.id === clubActual?.id) || CLUBS[0];
  const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
  const teamPasswordsLocal = clubInfo?.passwords?.equipos || TEAM_PASSWORDS;
  const [equipos, setEquipos] = React.useState([]);
  const [usuarios, setUsuarios] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [nuevoEquipo, setNuevoEquipo] = React.useState("");
  const [nuevaPassword, setNuevaPassword] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [msg, setMsg] = React.useState("");
  const [tab, setTab] = React.useState("equipos");

  React.useEffect(() => {
    const cargar = async () => {
      try {
        const [eq, us] = await Promise.all([
          loadEquipos(prefix).catch(() => []),
          loadUsuariosClub(prefix).catch(() => [])
        ]);
        if (eq.length === 0 && TEAMS.length > 0) {
          const migrados = TEAMS.map(nombre => ({
            nombre,
            password: Object.entries({...teamPasswordsLocal}).find(([k]) => k === nombre)?.[1] || "",
            creadoEn: new Date().toISOString()
          }));
          await saveEquipos(prefix, migrados).catch(() => {});
          setEquipos(migrados);
        } else {
          setEquipos(eq);
        }
        setUsuarios(us);
      } catch(e) {
        console.error("Error cargando gestion:", e);
      } finally {
        setLoading(false);
      }
    };
    cargar();
  }, [prefix]);

  const crearEquipo = async () => {
    if (!nuevoEquipo.trim() || !nuevaPassword.trim()) { setMsg("Pon nombre y contraseña."); return; }
    if (equipos.find(e => e.nombre === nuevoEquipo.trim())) { setMsg("Ya existe ese equipo."); return; }
    setSaving(true);
    const nuevo = { nombre: nuevoEquipo.trim(), password: nuevaPassword.trim().toUpperCase(), creadoEn: new Date().toISOString() };
    const nuevos = [...equipos, nuevo];
    const res = await saveEquipos(prefix, nuevos);
    if (res.ok) { setEquipos(nuevos); if (onEquiposChange) onEquiposChange(nuevos); setNuevoEquipo(""); setNuevaPassword(""); setMsg("Equipo creado."); }
    else { setMsg("Error: " + res.error); }
    setSaving(false);
    setTimeout(() => setMsg(""), 3000);
  };

  const [editando, setEditando] = React.useState(null);
  const [editNombre, setEditNombre] = React.useState("");
  const [editPassword, setEditPassword] = React.useState("");
  const [verJugadores, setVerJugadores] = React.useState(null);

  const eliminarEquipo = async (nombre) => {
    if (!window.confirm("Eliminar equipo " + nombre + "?")) return;
    const nuevos = equipos.filter(e => e.nombre !== nombre);
    await saveEquipos(prefix, nuevos);
    setEquipos(nuevos);
    if (onEquiposChange) onEquiposChange(nuevos);
  };

  const editarEquipo = (eq) => {
    setEditando(eq.nombre);
    setEditNombre(eq.nombre);
    setEditPassword(eq.password);
  };

  const guardarEdicion = async () => {
    if (!editNombre.trim() || !editPassword.trim()) return;
    const nuevos = equipos.map(e => e.nombre === editando
      ? { ...e, nombre: editNombre.trim(), password: editPassword.trim().toUpperCase() }
      : e
    );
    const sinDups = nuevos.filter((e, i, arr) => arr.findIndex(x => x.nombre === e.nombre) === i);
    await saveEquipos(prefix, sinDups);
    setEquipos(sinDups);
    if (onEquiposChange) onEquiposChange(sinDups);
    setEditando(null);
    setEditNombre("");
    setEditPassword("");
    setTimeout(() => window.location.reload(), 500);
  };

  const jugadoresDeEquipo = (nombreEquipo) => {
    return usuarios.filter(u => {
      const clubId = clubInfo?.id || "magdalena";
      const roles = u.roles || {};
      const clubRol = roles[clubId];
      const equipo = clubRol?.equipo || u.equipo || null;
      return equipo === nombreEquipo;
    });
  };

  const getRolUsuario = (u) => {
    const clubId = clubInfo?.id || "magdalena";
    const roles = u.roles || {};
    const clubRol = roles[clubId];
    return clubRol?.rol || u.rol || "familiar";
  };

  const ROL_COLOR = { coordinador: "red", entrenador: "blue", familiar: "zinc" };

  if (loading) return <div className="p-6 text-zinc-500 text-sm">Cargando...</div>;

  return (
    <div className="p-6 max-w-3xl">
      <h2 className="text-xl font-bold text-white mb-6">Gestión del Club</h2>
      <div className="flex gap-2 mb-6">
        <button onClick={() => setTab("equipos")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${tab==="equipos"?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>Equipos</button>
        <button onClick={() => setTab("usuarios")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${tab==="usuarios"?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>Usuarios ({usuarios.length})</button>
      </div>

      {tab === "equipos" && (
        <div>
          <Card className="mb-4">
            <h3 className="text-sm font-semibold text-white mb-3">Crear nuevo equipo</h3>
            <div className="flex gap-2 mb-2">
              <Input label="Nombre del equipo" value={nuevoEquipo} onChange={e => setNuevoEquipo(e.target.value)} placeholder="Ej: Infantil A" />
              <Input label="Contraseña" value={nuevaPassword} onChange={e => setNuevaPassword(e.target.value.toUpperCase())} placeholder="Ej: INF2026" />
            </div>
            {msg && <p className="text-xs text-green-400 mb-2">{msg}</p>}
            <Btn onClick={crearEquipo} disabled={saving}>{saving ? "Guardando..." : "Crear equipo"}</Btn>
          </Card>
          <Card>
            <h3 className="text-sm font-semibold text-white mb-3">Equipos actuales ({equipos.length})</h3>
            {equipos.length === 0 && <p className="text-zinc-500 text-sm">No hay equipos creados aun.</p>}
            {equipos.map(eq => (
              <div key={eq.nombre} className="py-2 border-b border-zinc-800 last:border-0">
                {editando === eq.nombre ? (
                  <div className="flex gap-2 items-end">
                    <Input label="Nombre" value={editNombre} onChange={e => setEditNombre(e.target.value)} />
                    <Input label="Contraseña" value={editPassword} onChange={e => setEditPassword(e.target.value.toUpperCase())} />
                    <Btn small onClick={guardarEdicion}>Guardar</Btn>
                    <Btn small variant="secondary" onClick={() => { setEditando(null); setEditNombre(""); setEditPassword(""); }}>Cancelar</Btn>
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <div className="flex-1">
                      <div className="text-white text-sm font-semibold">{eq.nombre}</div>
                      <div className="text-zinc-500 text-xs">Contraseña: <span className="text-zinc-300 font-mono">{eq.password}</span></div>
                    </div>
                    <Btn small variant="secondary" onClick={() => setVerJugadores(verJugadores === eq.nombre ? null : eq.nombre)}>
                      {verJugadores === eq.nombre ? "Ocultar" : "Jugadores"}
                    </Btn>
                    <Btn small onClick={() => editarEquipo(eq)}>Editar</Btn>
                    <Btn small variant="danger" onClick={() => eliminarEquipo(eq.nombre)}>Eliminar</Btn>
                  </div>
                )}
                {verJugadores === eq.nombre && (
                  <div className="mt-2 pl-3 border-l-2 border-zinc-700">
                    {jugadoresDeEquipo(eq.nombre).length === 0 ? (
                      <p className="text-zinc-600 text-xs">Sin entrenadores registrados</p>
                    ) : (
                      jugadoresDeEquipo(eq.nombre).map(u => (
                        <div key={u.email} className="flex items-center gap-2 py-1">
                          <div className="w-6 h-6 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                            {(u.nombre || u.email || "?")[0].toUpperCase()}
                          </div>
                          <div className="flex-1">
                            <div className="text-white text-xs font-semibold">{u.nombre}</div>
                            <div className="text-zinc-500 text-xs">{u.email}</div>
                          </div>
                          <Badge color={getRolUsuario(u) === "entrenador" ? "blue" : "zinc"}>{getRolUsuario(u)}</Badge>
                        </div>
                      ))
                    )}
                  </div>
                )}
              </div>
            ))}
          </Card>
        </div>
      )}

      {tab === "usuarios" && (
        <Card>
          <h3 className="text-sm font-semibold text-white mb-3">Usuarios registrados</h3>
          {usuarios.length === 0 && <p className="text-zinc-500 text-sm">No hay usuarios registrados.</p>}
          {usuarios.map(u => (
            <div key={u.email} className="flex items-center gap-3 py-2 border-b border-zinc-800 last:border-0">
              <div className="w-8 h-8 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                {(u.nombre || u.email || "?")[0].toUpperCase()}
              </div>
              <div className="flex-1">
                <div className="text-white text-sm font-semibold">{u.nombre || u.email}</div>
                <div className="text-zinc-500 text-xs">{u.email}</div>
                {u.equipo && <div className="text-zinc-500 text-xs">Equipo: {u.equipo}</div>}
              </div>
              {(() => {
                const clubId = clubActual?.id || "magdalena";
                const roles = u.roles || {};
                const clubRol = roles[clubId];
                const rol = clubRol?.rol || u.rol || "familiar";
                return <Badge color={ROL_COLOR[rol] || "zinc"}>{rol}</Badge>;
              })()}
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}


// ══════════════════════════════════════════════════════════════════════════════
// COMPONENTE: Microciclo semanal
// ══════════════════════════════════════════════════════════════════════════════
function MicrocicloSection({ team, data, onSave }) {
  const DIAS = ["Lunes","Martes","Miercoles","Jueves","Viernes","Sabado","Domingo"];
  const TIPOS = ["Descanso","Fisico","Tecnico","Tactico","Mixto","Partido","Recuperacion"];
  const INTENSIDADES = ["Baja","Media","Alta","Maxima"];
  const COLORES_TIPO = {
    "Descanso":"bg-zinc-800 text-zinc-400",
    "Fisico":"bg-orange-900 text-orange-300",
    "Tecnico":"bg-blue-900 text-blue-300",
    "Tactico":"bg-purple-900 text-purple-300",
    "Mixto":"bg-yellow-900 text-yellow-300",
    "Partido":"bg-red-900 text-red-300",
    "Recuperacion":"bg-green-900 text-green-300"
  };
  const COLORES_INT = { "Baja":"text-green-400","Media":"text-yellow-400","Alta":"text-orange-400","Maxima":"text-red-400" };

  const semanaActual = () => {
    const hoy = new Date();
    const lunes = new Date(hoy);
    lunes.setDate(hoy.getDate() - (hoy.getDay() || 7) + 1);
    return lunes.toISOString().slice(0, 10);
  };

  const [semana, setSemana] = React.useState(semanaActual());
  const [plan, setPlan] = React.useState(
    (data?.microciclos || {})[semanaActual()] || DIAS.map(d => ({ dia: d, tipo: "Descanso", objetivo: "", carga: 5, intensidad: "Media", notas: "" }))
  );
  const [guardando, setGuardando] = React.useState(false);

  React.useEffect(() => {
    const mc = (data?.microciclos || {})[semana];
    setPlan(mc || DIAS.map(d => ({ dia: d, tipo: "Descanso", objetivo: "", carga: 5, intensidad: "Media", notas: "" })));
  }, [semana, data]);

  const fechaISO = (i) => {
    const d = new Date(semana);
    d.setDate(d.getDate() + i);
    return d.toISOString().slice(0, 10);
  };
  const fechaDia = (i) => new Date(fechaISO(i)).toLocaleDateString("es-ES", { day: "numeric", month: "short" });

  const trainingsDe = (i) => (data?.trainings || []).filter(t => t.fecha === fechaISO(i));
  const matchesDe = (i) => (data?.matches || []).filter(m => m.fecha === fechaISO(i));

  const updateDia = (i, field, val) => {
    setPlan(plan.map((d, idx) => idx === i ? { ...d, [field]: val } : d));
  };

  const dataConPlan = (base) => ({
    ...base,
    microciclos: { ...(base?.microciclos || {}), [semana]: plan },
  });

  const guardar = async () => {
    setGuardando(true);
    await onSave(dataConPlan(data));
    setGuardando(false);
  };

  const crearSesion = async (i) => {
    const dia = plan[i];
    const nuevo = {
      id: Date.now(),
      fecha: fechaISO(i),
      desc: [dia.tipo !== "Descanso" ? "[" + dia.tipo + (dia.intensidad ? " · " + dia.intensidad : "") + "]" : "", dia.objetivo].filter(Boolean).join(" "),
      duracion: 90,
    };
    const trainings = [...(data.trainings || []), nuevo].sort((a, b) => (b.fecha || "").localeCompare(a.fecha || ""));
    setGuardando(true);
    await onSave(dataConPlan({ ...data, trainings }));
    setGuardando(false);
  };

  const crearSemana = async () => {
    const nuevos = [];
    plan.forEach((dia, i) => {
      if (dia.tipo === "Descanso" || dia.tipo === "Partido") return;
      if (trainingsDe(i).length > 0) return;
      nuevos.push({
        id: Date.now() + i,
        fecha: fechaISO(i),
        desc: ["[" + dia.tipo + (dia.intensidad ? " · " + dia.intensidad : "") + "]", dia.objetivo].filter(Boolean).join(" "),
        duracion: 90,
      });
    });
    if (!nuevos.length) { alert("Todos los días planificados ya tienen sesión creada."); return; }
    if (!window.confirm("¿Crear " + nuevos.length + " entrenamiento(s) a partir del plan?")) return;
    const trainings = [...(data.trainings || []), ...nuevos].sort((a, b) => (b.fecha || "").localeCompare(a.fecha || ""));
    setGuardando(true);
    await onSave(dataConPlan({ ...data, trainings }));
    setGuardando(false);
  };

  const semanaAnterior = () => { const d = new Date(semana); d.setDate(d.getDate() - 7); setSemana(d.toISOString().slice(0,10)); };
  const semanaSiguiente = () => { const d = new Date(semana); d.setDate(d.getDate() + 7); setSemana(d.toISOString().slice(0,10)); };

  const cargaTotal = plan.reduce((s, d) => d.tipo !== "Descanso" ? s + (d.carga || 0) : s, 0);
  const sesionesPlan = plan.filter(d => d.tipo !== "Descanso").length;
  const sesionesCreadas = plan.reduce((s, d, i) => s + trainingsDe(i).length, 0);

  return (
    <div className="max-w-5xl space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <button onClick={semanaAnterior} className="text-zinc-400 hover:text-white px-3 py-1.5 bg-zinc-800 rounded-lg">‹</button>
          <span className="text-zinc-300 text-sm font-medium">Semana {new Date(semana).toLocaleDateString("es-ES", {day:"numeric",month:"short"})}</span>
          <button onClick={semanaSiguiente} className="text-zinc-400 hover:text-white px-3 py-1.5 bg-zinc-800 rounded-lg">›</button>
        </div>
        <Btn small variant="secondary" onClick={crearSemana} disabled={guardando}>⚡ Crear sesiones de la semana</Btn>
      </div>

      <div className="grid grid-cols-3 gap-2">
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{sesionesCreadas}/{sesionesPlan}</div>
          <div className="text-zinc-500 text-xs">Creadas / plan</div>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{cargaTotal}</div>
          <div className="text-zinc-500 text-xs">Carga total</div>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{sesionesPlan > 0 ? (cargaTotal/sesionesPlan).toFixed(1) : 0}</div>
          <div className="text-zinc-500 text-xs">Media/sesión</div>
        </div>
      </div>

      <div className="space-y-2">
        {plan.map((dia, i) => {
          const trainsReales = trainingsDe(i);
          const matchesReales = matchesDe(i);
          return (
            <div key={i} className={`border rounded-xl p-3 ${dia.tipo === "Partido" || matchesReales.length ? "border-red-800 bg-red-900/10" : "border-zinc-800 bg-zinc-900"}`}>
              <div className="flex items-center gap-2 flex-wrap">
                <div className="w-20 flex-shrink-0">
                  <div className="text-white text-sm font-semibold">{dia.dia}</div>
                  <div className="text-zinc-500 text-xs">{fechaDia(i)}</div>
                </div>
                <select value={dia.tipo} onChange={e => updateDia(i, "tipo", e.target.value)}
                  className={`text-xs rounded-lg px-2 py-1.5 border-0 font-medium cursor-pointer ${COLORES_TIPO[dia.tipo] || "bg-zinc-800 text-zinc-300"}`}>
                  {TIPOS.map(t => <option key={t}>{t}</option>)}
                </select>
                {dia.tipo !== "Descanso" && (
                  <>
                    <input value={dia.objetivo} onChange={e => updateDia(i, "objetivo", e.target.value)}
                      placeholder="Objetivo del día..."
                      className="flex-1 min-w-28 bg-zinc-800 border border-zinc-700 rounded-lg px-2 py-1.5 text-zinc-100 text-xs focus:outline-none" />
                    <div className="flex items-center gap-1">
                      <span className="text-zinc-500 text-xs">Carga:</span>
                      <input type="range" min="1" max="10" value={dia.carga}
                        onChange={e => updateDia(i, "carga", parseInt(e.target.value))}
                        className="w-16 accent-red-600" />
                      <span className="text-white text-xs font-bold w-4">{dia.carga}</span>
                    </div>
                    <select value={dia.intensidad} onChange={e => updateDia(i, "intensidad", e.target.value)}
                      className={`text-xs bg-zinc-800 border border-zinc-700 rounded-lg px-2 py-1.5 font-medium ${COLORES_INT[dia.intensidad] || ""}`}>
                      {INTENSIDADES.map(t => <option key={t}>{t}</option>)}
                    </select>
                  </>
                )}
              </div>

              <div className="mt-2 flex items-center gap-2 flex-wrap">
                {matchesReales.map(m => (
                  <span key={m.id} className="text-xs px-2 py-1 rounded-full bg-red-900/40 border border-red-700 text-red-300">⚽ vs {m.rival}{m.resultado ? " · " + m.resultado : ""}</span>
                ))}
                {trainsReales.map(t => (
                  <span key={t.id} className="text-xs px-2 py-1 rounded-full bg-green-900/30 border border-green-700/60 text-green-300">✓ Sesión creada · {t.duracion || 90} min · {(t.tasks||[]).length} tareas</span>
                ))}
                {dia.tipo !== "Descanso" && dia.tipo !== "Partido" && trainsReales.length === 0 && (
                  <button onClick={() => crearSesion(i)} disabled={guardando}
                    className="text-xs px-2.5 py-1 rounded-full bg-zinc-800 border border-zinc-600 text-zinc-300 hover:border-zinc-400 hover:text-white transition-all">➕ Crear entrenamiento</button>
                )}
              </div>
            </div>
          );
        })}
      </div>
      <Btn onClick={guardar} disabled={guardando} className="w-full justify-center">
        {guardando ? "Guardando..." : "💾 Guardar microciclo"}
      </Btn>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// COMPONENTE: Barra de navegación inferior (solo móvil, 4 más recientes)
// ══════════════════════════════════════════════════════════════════════════════
function BottomNav({ sections, activeSection, setActiveSection, isCoord, teams, activeTeam, setActiveTeam }) {
  const [showMore, setShowMore] = React.useState(false);
  const storageKey = "mgd_nav_recientes_" + (isCoord ? "coord" : "entrenador");
  const [recientes, setRecientes] = React.useState(() => {
    try { return JSON.parse(localStorage.getItem(storageKey)) || []; } catch(e) { return []; }
  });

  const defaults = isCoord
    ? ["resumen", "plantilla", "entrenamientos", "partidos"]
    : ["plantilla", "entrenamientos", "partidos", "asistencia"];

  const validIds = sections.map(s => s.id);
  const barIds = [...new Set([...recientes, ...defaults])]
    .filter(id => validIds.includes(id))
    .slice(0, 4);

  // Orden estable: según el orden original de sections, no según recencia
  const main = sections.filter(s => barIds.includes(s.id));
  const more = sections.filter(s => !barIds.includes(s.id));
  const isMoreActive = more.some(s => s.id === activeSection);

  const go = (id) => {
    setActiveSection(id);
    setShowMore(false);
    const nuevos = [id, ...recientes.filter(x => x !== id)].slice(0, 8);
    setRecientes(nuevos);
    try { localStorage.setItem(storageKey, JSON.stringify(nuevos)); } catch(e) {}
  };

  return (
    <>
      {showMore && (
        <div className="md:hidden fixed inset-0 z-40 bg-black/60" onClick={() => setShowMore(false)}>
          <div className="absolute bottom-16 inset-x-0 bg-zinc-900 border-t border-zinc-700 rounded-t-2xl p-4 max-h-[70vh] overflow-auto"
            onClick={e => e.stopPropagation()}>
            <div className="w-10 h-1 bg-zinc-700 rounded-full mx-auto mb-4" />
            {isCoord && (
              <div className="mb-4">
                <p className="text-xs text-zinc-500 uppercase tracking-wider mb-2">Equipo</p>
                <div className="flex flex-wrap gap-1.5">
                  {teams.map(t => (
                    <button key={t} onClick={() => { setActiveTeam(t); }}
                      className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-all ${activeTeam === t ? "bg-red-700 border-red-500 text-white" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                      {t}
                    </button>
                  ))}
                </div>
              </div>
            )}
            <p className="text-xs text-zinc-500 uppercase tracking-wider mb-2">Más secciones</p>
            <div className="grid grid-cols-3 gap-2">
              {more.map(s => (
                <button key={s.id} onClick={() => go(s.id)}
                  className={`flex flex-col items-center gap-1 py-3 rounded-xl border transition-all ${activeSection === s.id ? "bg-red-900/40 border-red-700 text-red-300" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                  <span className="text-xl">{s.icon}</span>
                  <span className="text-xs font-medium text-center leading-tight">{s.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 inset-x-0 z-50 bg-zinc-900 border-t border-zinc-800 flex"
        style={{ paddingBottom: "env(safe-area-inset-bottom)" }}>
        {main.map(s => (
          <button key={s.id} onClick={() => go(s.id)}
            className={`flex-1 flex flex-col items-center gap-0.5 py-2 transition-all ${activeSection === s.id ? "text-red-400" : "text-zinc-500"}`}>
            <span className="text-lg">{s.icon}</span>
            <span className="text-[10px] font-medium">{s.label.length > 10 ? s.label.slice(0, 9) + "…" : s.label}</span>
            {activeSection === s.id && <span className="w-5 h-0.5 bg-red-500 rounded-full" />}
          </button>
        ))}
        <button onClick={() => setShowMore(v => !v)}
          className={`flex-1 flex flex-col items-center gap-0.5 py-2 transition-all ${showMore || isMoreActive ? "text-red-400" : "text-zinc-500"}`}>
          <span className="text-lg">☰</span>
          <span className="text-[10px] font-medium">Más</span>
          {isMoreActive && !showMore && <span className="w-5 h-0.5 bg-red-500 rounded-full" />}
        </button>
      </div>
    </>
  );
}


// ══════════════════════════════════════════════════════════════════════════════
// SECTION: Avisos (notificaciones push)
// ══════════════════════════════════════════════════════════════════════════════
function AvisosSection({ isCoord, teamAccess, teams, currentUser, clubId }) {
  const [titulo, setTitulo] = React.useState("");
  const [mensaje, setMensaje] = React.useState("");
  const [destino, setDestino] = React.useState(isCoord ? "todos" : teamAccess);
  const [avisos, setAvisos] = React.useState([]);
  const [enviando, setEnviando] = React.useState(false);
  const [pushMsg, setPushMsg] = React.useState("");
  const [pushOk, setPushOk] = React.useState(false);

  React.useEffect(() => {
    cargarAvisos(clubId).then(setAvisos).catch(() => {});
    try { setPushOk(Notification.permission === "granted"); } catch(e) {}
  }, [clubId]);

  const activar = async () => {
    setPushMsg("Activando...");
    const res = await activarPush({
      email: currentUser?.email,
      nombre: currentUser?.nombre,
      rol: isCoord ? "coordinador" : (teamAccess ? "entrenador" : "familiar"),
      equipo: teamAccess || "",
      clubId,
    });
    if (res.ok) { setPushOk(true); setPushMsg("✅ Notificaciones activadas en este dispositivo"); }
    else setPushMsg("❌ " + res.error);
  };

  const enviar = async () => {
    if (!titulo.trim() || !mensaje.trim()) return;
    setEnviando(true);
    await enviarAviso({ titulo, mensaje, destino, clubId, creadoPor: currentUser?.nombre || "—" });
    setTitulo(""); setMensaje("");
    setEnviando(false);
    cargarAvisos(clubId).then(setAvisos).catch(() => {});
  };

  const puedeEnviar = isCoord || !!teamAccess;

  return (
    <div className="space-y-4">
      <h2 className="text-xl font-bold text-white">🔔 Avisos</h2>

      <Card className={pushOk ? "border-green-900/50" : "border-yellow-900/50"}>
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div>
            <p className="text-white font-semibold text-sm">{pushOk ? "Notificaciones activadas" : "Activa las notificaciones"}</p>
            <p className="text-zinc-500 text-xs">{pushOk ? "Recibirás los avisos en este dispositivo." : "Para recibir avisos del club en este dispositivo."}</p>
          </div>
          {!pushOk && <Btn onClick={activar}>🔔 Activar</Btn>}
        </div>
        {pushMsg && <p className="text-zinc-400 text-xs mt-2">{pushMsg}</p>}
      </Card>

      {puedeEnviar && (
        <Card className="border-red-900/50">
          <h3 className="text-sm font-bold text-zinc-300 mb-3">Enviar aviso</h3>
          <div className="space-y-3">
            <Input label="Título" value={titulo} onChange={e => setTitulo(e.target.value)} placeholder="Ej: Cambio de horario" />
            <Textarea label="Mensaje" value={mensaje} onChange={e => setMensaje(e.target.value)} placeholder="Escribe el aviso..." rows={3} />
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Enviar a</label>
              <div className="flex flex-wrap gap-1.5">
                {isCoord && (
                  <button onClick={() => setDestino("todos")}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-all ${destino === "todos" ? "bg-red-700 border-red-500 text-white" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                    📢 Todo el club
                  </button>
                )}
                {(isCoord ? teams : [teamAccess]).map(t => (
                  <button key={t} onClick={() => setDestino(t)}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-all ${destino === t ? "bg-red-700 border-red-500 text-white" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                    {t}
                  </button>
                ))}
              </div>
            </div>
            <Btn onClick={enviar} disabled={enviando || !titulo.trim() || !mensaje.trim()}>
              {enviando ? "Enviando..." : "📤 Enviar aviso"}
            </Btn>
          </div>
        </Card>
      )}

      <div className="space-y-2">
        <p className="text-xs text-zinc-500 uppercase tracking-wider">Últimos avisos</p>
        {avisos.length === 0 && <p className="text-zinc-500 text-sm">No hay avisos todavía.</p>}
        {avisos.map(a => (
          <Card key={a.id}>
            <div className="flex items-center gap-2 flex-wrap mb-1">
              <span className="text-white font-semibold text-sm">{a.titulo}</span>
              <Badge color={a.destino === "todos" ? "red" : "blue"}>{a.destino === "todos" ? "📢 Todo el club" : a.destino}</Badge>
            </div>
            <p className="text-zinc-300 text-sm">{a.mensaje}</p>
            <p className="text-zinc-600 text-xs mt-1">
              {a.creadoPor}{a.fecha?.toDate ? " · " + a.fecha.toDate().toLocaleString("es-ES", {day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}) : ""}
            </p>
          </Card>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  // ─────────────────────────────────────────────────────────────────
  // MODO CLUB UNICO: mientras solo esta confirmado La Magdalena,
  // arrancamos directo en su login y ocultamos selector/otros clubes.
  // Para reactivar el modo multi-club, pon SINGLE_CLUB_ID en null.
  // ─────────────────────────────────────────────────────────────────
  const SINGLE_CLUB_ID = "magdalena";
  const getSavedClub = () => {
    try {
      const saved = localStorage.getItem("mgd_club");
      if (saved) {
        const { CLUBS: C } = require ? { CLUBS } : { CLUBS };
        return CLUBS.find(c => c.id === saved) || null;
      }
    } catch(e) {}
    return null;
  };
  const savedClub = (() => {
    try {
      const saved = localStorage.getItem("mgd_club");
      return saved ? CLUBS.find(c => c.id === saved) || null : null;
    } catch(e) { return null; }
  })();
  const savedSession = (() => {
    try {
      const s = JSON.parse(localStorage.getItem("mgd_session"));
      if (!s || !s.user) return null;
      const clubId = s.clubId || "magdalena";
      // En modo club unico, ignoramos y limpiamos cualquier sesion que no
      // sea del club activo (p.ej. una sesion vieja de pruebas de otro
      // club), para no arrancar nunca en un club que deberia estar oculto.
      if (SINGLE_CLUB_ID && clubId !== SINGLE_CLUB_ID) {
        localStorage.removeItem("mgd_session");
        return null;
      }
      // Verificar que tiene roles por club validos
      const roles = s.user.roles || {};
      const clubRol = roles[clubId];
      if (!clubRol && !(clubId === "magdalena" && s.user.rol)) {
        localStorage.removeItem("mgd_session");
        return null;
      }
      // Asegurar rolActual correcto para el club
      if (clubRol) {
        s.user.rolActual = clubRol.rol;
        s.user.equipoActual = clubRol.equipo;
      }
      return s;
    } catch(e) { return null; }
  })();
  const [authState, setAuthState] = useState(savedSession ? "app" : (SINGLE_CLUB_ID ? "home" : "selector"));
  const [clubActual, setClubActual] = useState(savedSession ? CLUBS.find(c => c.id === savedSession.clubId) || CLUBS[0] : (SINGLE_CLUB_ID ? (CLUBS.find(c => c.id === SINGLE_CLUB_ID) || CLUBS[0]) : null));
  const [currentUser, setCurrentUser] = useState(savedSession?.user || null);
  const savedRolRaw = savedSession?.user?.rolActual || savedSession?.user?.rol;
  const savedRole = savedRolRaw === "coordinador" ? "coordinator" : savedRolRaw === "entrenador" ? "trainer" : savedRolRaw === "familiar" ? "familiar" : null;
  const [role, setRole] = useState(savedRole);
  const [teamAccess, setTeamAccess] = useState(savedSession?.user?.equipo || null);
  const [password, setPassword] = useState("");
  const [teamPasswords, setTeamPasswords] = useState({});
  const [globalTasks, setGlobalTasks] = useState([]);
  const [coordProfile, setCoordProfile] = useState(savedSession?.user?.nombre || "");
  const [equiposDinamicos, setEquiposDinamicos] = useState([]);
  const [equipoAbierto, setEquipoAbierto] = useState(null);
  // Cargar equipos al inicializar si hay sesion
  React.useEffect(() => {
    if (authState === "app" && clubActual?.id) {
      const { CLUBS: C } = { CLUBS };
      const clubInfo = CLUBS.find(c => c.id === clubActual.id) || CLUBS[0];
      const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
      loadEquipos(prefix).then(eqs => {
        if (eqs && eqs.length > 0) setEquiposDinamicos(eqs.map(e => e.nombre));
      }).catch(() => {});
    }
  }, []);
  const [showProfilePicker, setShowProfilePicker] = useState(false); // nunca mostrar si hay sesion guardada
  const [teamInput, setTeamInput] = useState("Coordinador");
  const [loginError, setLoginError] = useState("");

  const [db, setDb] = useState(null);
  const [loading, setLoading] = useState(true);
  const [seasons, setSeasons] = useState([]);

  const [activeTeam, setActiveTeam] = useState(savedSession?.user?.equipo || null);
  const [activeSection, setActiveSection] = useState("plantilla");
  const [ajustesVista, setAjustesVista] = useState("club");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [informesPlayer, setInformesPlayer] = useState(null);

  useEffect(() => {
    const handler = (e) => {
      setInformesPlayer(e.detail);
      setActiveSection("informes");
    };
    window.addEventListener("openInformes", handler);
    return () => window.removeEventListener("openInformes", handler);
  }, []);

  useEffect(() => {
    const handler = () => { setAuthState("home"); };
    window.addEventListener("volverSelector", handler);
    return () => window.removeEventListener("volverSelector", handler);
  }, []);

  const [alertaEntrenamiento, setAlertaEntrenamiento] = useState(null);
  useEffect(() => {
    if (authState !== "app" || !db || !activeTeam) return;
    const ahora = new Date();
    const teamData = db[activeTeam] || {};
    const entrenamientos = teamData.trainings || [];
    const proximo = entrenamientos.find(e => {
      if (!e.date) return false;
      const fechaHora = new Date(e.date + (e.time ? "T" + e.time : "T18:00"));
      const diff = (fechaHora - ahora) / 60000;
      return diff >= 0 && diff <= 30;
    });
    if (proximo) setAlertaEntrenamiento(proximo);
  }, [authState, db, activeTeam]);

  useEffect(() => {
    if (authState === "app" && clubActual) {
      const clubInfo = CLUBS.find(c => c.id === clubActual.id) || CLUBS[0];
      const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
      loadEquipos(prefix).then(eqs => {
        if (eqs && eqs.length > 0) {
          setEquiposDinamicos(eqs.map(e => e.nombre));
        }
      }).catch(() => {});
    }
  }, [authState, clubActual?.id]);

  const isCoord = role === "coordinator";

  const sections = [
    ...(isCoord ? [{ id: "resumen", label: "Resumen", icon: "📊" }] : []),
    ...(isCoord ? [{ id: "entrenadores", label: "Entrenadores", icon: "🧑‍🏫" }] : []),
    ...(isCoord ? [{ id: "gestion", label: "Ajustes", icon: "⚙️" }] : []),
    ...(!isCoord ? [{ id: "avisos", label: "Avisos", icon: "🔔" }] : []),
    { id: "plantilla", label: "Plantilla", icon: "👥" },
    { id: "parte", label: "Parte lesiones", icon: "🩹" },
    { id: "entrenamientos", label: "Entrenamientos", icon: "🏃" },
    { id: "tareas", label: "Tareas", icon: "🗂" },
    { id: "partidos", label: "Partidos", icon: "⚽" },
    { id: "clasificacion", label: "Clasificaciones", icon: "🏆" },
    { id: "asistencia", label: "Asistencia", icon: "📋" },
  ];

  useEffect(() => {
    Promise.all([loadData(), loadSeasons()]).then(([d, s]) => {
      // load passwords
      try { const raw = localStorage.getItem("cdmag_passwords"); if(raw) setTeamPasswords(JSON.parse(raw)); } catch(e) {}
      // globalTasks se carga de Firebase via loadData
      const dbData = d || initState();
      setDb(dbData);
      if (dbData.__globalTasks) setGlobalTasks(dbData.__globalTasks);
      setSeasons(s || []);
      setLoading(false);
    });
  }, []);

  const TEAM_PASSWORDS = {
    "Escoleta": "KFW",
    "Prebenjamín": "ZBN",
    "Benjamín C": "TXR",
    "Benjamín B": "PLH",
    "Benjamín A": "DJV",
    "Alevín B": "WCQ",
    "Alevín A": "NYS",
    "Transición": "HQV",
    "Infantil B": "RGK",
    "Infantil A": "BTP",
    "Cadete": "XMJ",
    "Juvenil": "FVL",
  };

  const login = () => {
    if (teamInput === "Coordinador" && password === "MGD") {
      setRole("coordinator");
      setTeamAccess(null);
      setActiveTeam(TEAMS[0]);
      setActiveSection("resumen");
      setShowProfilePicker(true);
    } else if (teamInput !== "Coordinador" && ({...TEAM_PASSWORDS, ...teamPasswords})[teamInput] === password) {
      setRole("trainer");
      setTeamAccess(teamInput);
      setActiveTeam(teamInput);
      setAuthState("app");
    } else {
      setLoginError("Contraseña incorrecta.");
    }
  };

  const updateTeamData = async (team, newData) => {
    if (window._setSaving) window._setSaving(true);
    let freshDb;
    try {
      freshDb = await loadData();
      if (freshDb) setDb(freshDb);
    } catch(e) {
      freshDb = db;
    }
    const cleanTeam = (d) => ({
      ...d,
      trainings: (d.trainings || []).map(t => ({
        ...t,
        tasks: (t.tasks || []).map(task => ({
          ...task,
          pizarra: (task.pizarra || []).filter(el => el != null && el.type).map(el => (
            el.type === "drawing"
              ? { id: el.id, type: el.type, path: el.path, color: el.color, size: el.size }
              : { id: el.id, type: el.type, x: el.x, y: el.y, x2: el.x2, y2: el.y2, color: el.color || (el.type||"").replace("player_","") || "red", num: el.num ?? el.number, material: el.material }
          ))
        }))
      })),
      tasks: (d.tasks || []).map(task => ({
        ...task,
        pizarra: (task.pizarra || []).filter(el => el != null && el.type).map(el => (
          el.type === "drawing"
            ? { id: el.id, type: el.type, path: el.path, color: el.color, size: el.size }
            : { id: el.id, type: el.type, x: el.x, y: el.y, x2: el.x2, y2: el.y2, color: el.color || (el.type||"").replace("player_","") || "red", num: el.num ?? el.number, material: el.material }
        ))
      }))
    });
    const newDb = { ...(freshDb || db), [team]: cleanTeam(newData) };
    setDb(newDb);
    await saveData(newDb);
    setTimeout(() => { if (window._setSaving) window._setSaving(false); }, 2000);
  };

  const saveGlobalTasks = async (tasks) => {
    setGlobalTasks(tasks);
    const newDb = { ...db, __globalTasks: tasks };
    setDb(newDb);
    await saveData(newDb);
  };

  const savePasswords = async (newPwds) => {
    setTeamPasswords(newPwds);
    localStorage.setItem("cdmag_passwords", JSON.stringify(newPwds));
  };

  const archiveSeason = async () => {
    const fresh = initState();
    TEAMS.forEach(t => {
      fresh[t].players = db[t]?.players || [];
      fresh[t].coaches = db[t]?.coaches || [];
      fresh[t].tasks = db[t]?.tasks || [];
    });
    setDb(fresh);
    await saveData(fresh);
    const updated = await loadSeasons();
    setSeasons(updated || []);
  };

  const restoreSeason = async (seasonData) => {
    setDb(seasonData);
    await saveData(seasonData);
  };

  const handleLoginUsuario = (user) => {
    setCurrentUser(user);
    const r = user.rolActual || user.rol || "familiar";
    if (r === "coordinador") {
      setRole("coordinator");
      setTeamAccess(null);
      setActiveTeam(TEAMS[0]);
      setActiveSection("resumen");
      setCoordProfile(user.nombre || "Coordinador");
      setShowProfilePicker(false);
      setAuthState("app");
    } else if (r === "entrenador") {
      const equipo = user.equipo && TEAMS.includes(user.equipo) ? user.equipo : TEAMS[0];
      setRole("trainer");
      setTeamAccess(equipo);
      setActiveTeam(equipo);
      setActiveSection("plantilla");
      setAuthState("app");
    } else {
      setRole("familiar");
      setActiveTeam(TEAMS[0]);
      setActiveSection("plantilla");
      setAuthState("app");
    }
  };
  const teamsToUse = equiposDinamicos.length > 0 ? equiposDinamicos : TEAMS;
  const availableTeams = isCoord ? teamsToUse : [teamAccess];

  if (loading) return (
    <div className="min-h-screen bg-zinc-950 flex items-center justify-center">
      <div className="text-zinc-400 text-sm animate-pulse">Cargando...</div>
    </div>
  );

  if (showProfilePicker) return (
    <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-4">
      <div className="w-full max-w-sm">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-red-700 mb-4"><span className="text-2xl">⚽</span></div>
          <h1 className="text-xl font-black text-white">¿Quién eres?</h1>
          <p className="text-zinc-500 text-sm mt-1">Selecciona tu perfil de coordinador</p>
        </div>
        <div className="grid grid-cols-2 gap-3">
          {COORDINATORS.map(name => (
            <button key={name} onClick={() => { setCoordProfile(name); setShowProfilePicker(false); setAuthState("app"); }}
              className="bg-zinc-800 hover:bg-red-900/60 border border-zinc-700 hover:border-red-700 rounded-xl p-4 text-white font-semibold text-sm transition-all">
              {name}
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  if (alertaEntrenamiento && authState === "app") return (
    <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4">
      <div className="bg-zinc-900 border border-zinc-700 rounded-2xl p-6 max-w-sm w-full">
        <div className="text-center mb-4">
          <div className="text-4xl mb-2">🏃</div>
          <h2 className="text-white text-xl font-bold">Entrenamiento en breve</h2>
          <p className="text-zinc-400 text-sm mt-1">{alertaEntrenamiento.date} {alertaEntrenamiento.time || ""}</p>
          {alertaEntrenamiento.description && <p className="text-zinc-300 text-sm mt-1">{alertaEntrenamiento.description}</p>}
        </div>
        <div className="flex gap-2">
          <Btn className="flex-1 justify-center" onClick={() => { setActiveSection("entrenamientos"); setAlertaEntrenamiento(null); }}>
            Ir a asistencia
          </Btn>
          <Btn variant="secondary" className="flex-1 justify-center" onClick={() => setAlertaEntrenamiento(null)}>
            Ahora no
          </Btn>
        </div>
      </div>
    </div>
  );

  if (authState === "selector") return (
    <SelectorClubes onSelect={(club) => {
      setClubActual(club);
      try { localStorage.setItem("mgd_club", JSON.stringify(club.id)); } catch(e) {}
      try {
        const sess = JSON.parse(localStorage.getItem("mgd_session"));
        if (sess && sess.clubId !== club.id) {
          localStorage.removeItem("mgd_session");
          setCurrentUser(null);
          setRole(null);
        }
      } catch(e) {}
      if (club.id === "internacional") {
        const demoUser = { nombre: "Demo", email: "demo@internacional.com", rolActual: "admin", rol: "admin" };
        setCurrentUser(demoUser);
        try { localStorage.setItem("mgd_session", JSON.stringify({ user: demoUser, clubId: "internacional" })); } catch(e) {}
        setAuthState("app");
      } else {
        setAuthState("home");
      }
    }} />
  );
  if (authState === "home") return <HomePublica club={clubActual} onAcceder={() => setAuthState("login")} onVolver={SINGLE_CLUB_ID ? null : () => setAuthState("selector")} currentUser={currentUser} onEntrarDirecto={() => { setAuthState("app"); if(savedRole === "coordinator") { setActiveTeam(TEAMS[0]); setActiveSection("resumen"); } }} />;
  if (authState === "login" && clubActual?.id === "internacional") {
    const demoUser = { nombre: "Coordinador", email: "demo@internacional.com", rolActual: "admin", rol: "admin" };
    try { localStorage.setItem("mgd_session", JSON.stringify({ user: demoUser, clubId: "internacional" })); } catch(e) {}
    setCurrentUser(demoUser);
    setAuthState("app");
    return null;
  }
  if (authState === "login") return (
    <LoginScreen
      club={clubActual}
      onVolver={() => setAuthState("home")}
      onLoginOk={handleLoginUsuario}
      onIrRegistro={() => setAuthState("register")}
      onLoginLegacy={() => setAuthState("login_legacy")}
    />
  );
  if (authState === "register") return (
    <RegistroScreen
      club={clubActual}
      onVolver={() => setAuthState("login")}
      onRegistroOk={handleLoginUsuario}
    />
  );
  if (authState === "login_legacy") return (
    <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-4">
      <div className="w-full max-w-sm">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-red-700 mb-4 shadow-lg shadow-red-900/50">
            <span className="text-3xl">⚽</span>
          </div>
          <h1 className="text-2xl font-black text-white tracking-tight">CD La Magdalena</h1>
          <p className="text-zinc-500 text-sm mt-1">Acceso con clave de equipo</p>
        </div>
        <Card className="border-zinc-700">
          <div className="space-y-4">
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Rol / Equipo</label>
              <select value={teamInput} onChange={e => setTeamInput(e.target.value)}
                className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm focus:outline-none focus:border-red-600 w-full">
                {["Coordinador", ...TEAMS].map(t => <option key={t}>{t}</option>)}
              </select>
            </div>
            <Input label="Contrasena" type="password" value={password}
              onChange={e => { setPassword(e.target.value); setLoginError(""); }}
              onKeyDown={e => e.key === "Enter" && login()}
              placeholder="Introduce tu clave" />
            {loginError && <p className="text-red-400 text-xs">{loginError}</p>}
            <Btn onClick={login} className="w-full justify-center">Entrar</Btn>
            <button onClick={() => setAuthState("login")} className="w-full text-xs text-zinc-600 hover:text-zinc-400 text-center">
              Volver al login principal
            </button>
          </div>
        </Card>
      </div>
    </div>
  );

  if (showProfilePicker) return (
    <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-4">
      <div className="w-full max-w-sm">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-red-700 mb-4">
            <span className="text-2xl">⚽</span>
          </div>
          <h1 className="text-xl font-black text-white">¿Quién eres?</h1>
          <p className="text-zinc-500 text-sm mt-1">Selecciona tu perfil de coordinador</p>
        </div>
        <div className="grid grid-cols-2 gap-3">
          {COORDINATORS.map(name => (
            <button key={name} onClick={() => { setCoordProfile(name); setShowProfilePicker(false); setAuthState("app"); }}
              className="bg-zinc-800 hover:bg-red-900/60 border border-zinc-700 hover:border-red-700 rounded-xl p-4 text-white font-semibold text-sm transition-all">
              {name}
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  if (authState === "app" && clubActual?.id === "amics") return <AmicsApp currentUser={currentUser} onVolver={() => setAuthState("home")} onSalir={() => { try { localStorage.removeItem("mgd_session"); } catch(e) {} setAuthState("selector"); setCurrentUser(null); setClubActual(null); setRole(null); }} />;
  if (authState === "app" && clubActual?.id === "internacional") return <InternacionalApp currentUser={currentUser} onVolver={() => setAuthState("home")} onSalir={() => { try { localStorage.removeItem("mgd_session"); } catch(e) {} setAuthState("selector"); setCurrentUser(null); setClubActual(null); setRole(null); }} />;
  const teamData = db[activeTeam] || { players: [], trainings: [], matches: [], attendance: [] };

  return (
    <div className="min-h-screen bg-zinc-950 flex text-zinc-100" style={{ fontFamily: "'Segoe UI', sans-serif" }}>
      {/* Sidebar */}
      <div className={`${sidebarOpen ? "md:w-64" : "md:w-0 overflow-hidden"} hidden md:flex transition-all duration-300 bg-zinc-900 border-r border-zinc-800 flex-col shrink-0`}>
        {/* Header */}
        <div className="p-4 border-b border-zinc-800">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 rounded-full flex items-center justify-center text-sm" style={{background: clubActual?.colorAccent || "#b91c1c"}}>{clubActual?.emoji || "⚽"}</div>
            <div>
              <div className="font-black text-white text-sm">{clubActual?.nombreCorto || "CD La Magdalena"}</div>
              <div className="text-xs text-zinc-400">{currentUser?.nombre || coordProfile}</div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge color={isCoord ? "red" : "blue"}>{isCoord ? "Coordinador" : "Entrenador"}</Badge>
            {currentUser?.equipo && <span className="text-xs text-zinc-500">{currentUser.equipo}</span>}
          </div>
        </div>

        {/* Team selector */}
        {isCoord && (
          <div className="p-3 border-b border-zinc-800">
            <button onClick={() => setEquipoAbierto(equipoAbierto === "__lista__" ? null : "__lista__")}
              className="w-full flex items-center justify-between text-xs text-zinc-500 uppercase tracking-wider mb-2 hover:text-white transition-all">
              <span>Equipo</span>
              <span>{equipoAbierto === "__lista__" ? "▲" : "▼"}</span>
            </button>
            {equipoAbierto === "__lista__" && <div>
            {teamsToUse.map(t => (
              <button key={t} onClick={() => setActiveTeam(t)}
                className={`w-full text-left px-3 py-2 rounded text-sm transition-all ${activeTeam === t ? "bg-red-900/40 text-red-300 font-semibold" : "text-zinc-400 hover:bg-zinc-800 hover:text-white"}`}>
                {t}
              </button>
            ))}
          </div>}
          </div>
        )}      {!isCoord && (
          <div className="p-3 border-b border-zinc-800">
            <p className="text-xs text-zinc-500 uppercase tracking-wider mb-1">Tu equipo</p>
            <p className="text-white font-semibold text-sm">{teamAccess}</p>
          </div>
        )}

        {/* Sections */}
        <nav className="p-3 flex-1">
          <p className="text-xs text-zinc-500 uppercase tracking-wider mb-2">Secciones</p>
          {sections.map(s => (
            <button
              key={s.id}
              onClick={() => setActiveSection(s.id)}
              className={`w-full text-left px-3 py-2 rounded text-sm transition-all flex items-center gap-2 ${
                activeSection === s.id ? "bg-red-900/40 text-red-300 font-semibold" : "text-zinc-400 hover:bg-zinc-800 hover:text-white"
              }`}
            >
              <span>{s.icon}</span>{s.label}
            </button>
          ))}
        </nav>

        {/* Logout */}
        <div className="p-3 border-t border-zinc-800">
          <Btn variant="ghost" small className="w-full justify-center" onClick={() => { setAuthState("login"); setPassword(""); }}>
            Cerrar sesión
          </Btn>
        </div>
      </div>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Topbar */}
        <div className="h-14 bg-zinc-900 border-b border-zinc-800 flex items-center px-4 gap-3 shrink-0">
          <button
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="text-zinc-400 hover:text-white text-xl w-8 h-8 hidden md:flex items-center justify-center rounded hover:bg-zinc-800 transition-all"
          >☰</button>
          <button
            onClick={() => setAuthState("home")}
            className="text-zinc-500 hover:text-white text-xs px-3 py-1.5 rounded border border-zinc-800 hover:border-zinc-600 transition-all ml-1"
          >🏠 Inicio</button>
          <button
            onClick={() => { try { localStorage.removeItem("mgd_session"); } catch(e) {} setAuthState(SINGLE_CLUB_ID ? "home" : "selector"); setCurrentUser(null); setClubActual(SINGLE_CLUB_ID ? (CLUBS.find(c => c.id === SINGLE_CLUB_ID) || CLUBS[0]) : null); setRole(null); }}
            className="text-zinc-500 hover:text-red-400 text-xs px-3 py-1.5 rounded border border-zinc-800 hover:border-red-800 transition-all"
          >Salir</button>
          <span className="text-white font-semibold">
            {sections.find(s => s.id === activeSection)?.icon} {sections.find(s => s.id === activeSection)?.label}
            <span className="text-zinc-500 font-normal ml-2">— {activeTeam}</span>
          </span>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto p-5 pb-24 md:p-8 md:pb-8">
          <div className="max-w-4xl mx-auto">
            {activeSection === "resumen" && isCoord && (
              <ResumenSection db={db} />
            )}
            {activeSection === "entrenadores" && isCoord && (
              <EntrenadoresSection db={db} onSaveTeam={(team, data) => updateTeamData(team, data)} coordProfile={coordProfile} />
            )}
      {activeSection === "gestion" && isCoord && (
              <div className="space-y-4">
                <div className="flex gap-2">
                  <button onClick={() => setAjustesVista("club")}
                    className={`px-4 py-2 rounded-lg text-sm border transition-all ${ajustesVista === "club" ? "bg-red-700 border-red-500 text-white font-semibold" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>🏟️ Club</button>
                  <button onClick={() => setAjustesVista("avisos")}
                    className={`px-4 py-2 rounded-lg text-sm border transition-all ${ajustesVista === "avisos" ? "bg-red-700 border-red-500 text-white font-semibold" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>🔔 Avisos</button>
                </div>
                {ajustesVista === "club" && (
                  <div>
                    <GestionClubSection clubActual={clubActual} onEquiposChange={(eqs) => setEquiposDinamicos(eqs.map(e => e.nombre))} />
                    <GestionSection db={db} onArchive={archiveSeason} onRestore={restoreSeason} passwords={{...TEAM_PASSWORDS, ...teamPasswords}} onSavePasswords={savePasswords} />
                  </div>
                )}
                {ajustesVista === "avisos" && (
                  <AvisosSection isCoord={isCoord} teamAccess={teamAccess} teams={teamsToUse} currentUser={currentUser} clubId={clubActual?.id || "magdalena"} />
                )}
              </div>
            )}
            {activeSection === "avisos" && (
              <AvisosSection isCoord={isCoord} teamAccess={teamAccess} teams={teamsToUse} currentUser={currentUser} clubId={clubActual?.id || "magdalena"} />
            )}
            {activeSection === "parte" && (
              <ParteLesionesSection teams={teamsToUse} db={db} isCoord={isCoord} teamAccess={teamAccess} />
            )}
            {activeSection === "plantilla" && (
              <PlantillaSection team={activeTeam} data={teamData} onSave={d => updateTeamData(activeTeam, d)} isCoord={isCoord} seasons={seasons} db={db} clubActual={clubActual} />
            )}

            {activeSection === "informes" && informesPlayer && (
              <InformesSection
                player={informesPlayer.player}
                team={informesPlayer.team}
                data={teamData}
                onSave={d => updateTeamData(activeTeam, d)}
                onBack={() => setActiveSection("plantilla")}
              />
            )}
            {activeSection === "entrenamientos" && (
              <EntrenamientosSection team={activeTeam} data={teamData} onSave={d => updateTeamData(activeTeam, d)} isCoord={isCoord} />
            )}
            {activeSection === "tareas" && (
              <TareasSection team={activeTeam} data={teamData} onSave={d => updateTeamData(activeTeam, d)} globalTasks={globalTasks} onSaveGlobal={saveGlobalTasks} isCoord={isCoord} />
            )}
            {activeSection === "partidos" && (
              <PartidosSection team={activeTeam} data={teamData} onSave={d => updateTeamData(activeTeam, d)} isCoord={isCoord} db={db} />
            )}
            {activeSection === "clasificacion" && (
              <ClasificacionSection team={activeTeam} data={teamData} db={db} isCoord={isCoord} />
            )}
            {activeSection === "asistencia" && (
              <AsistenciaSection team={activeTeam} data={teamData} onSave={d => updateTeamData(activeTeam, d)} isCoord={isCoord} />
            )}
          </div>
        </div>
      </div>
      <BottomNav
        sections={sections}
        activeSection={activeSection}
        setActiveSection={setActiveSection}
        isCoord={isCoord}
        teams={teamsToUse}
        activeTeam={activeTeam}
        setActiveTeam={setActiveTeam}
      />
    </div>
  );
}
